using AtlasPca;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.Crypto.Signers;
using Xunit;
using D = System.Collections.Generic.Dictionary<string, object?>;

namespace AtlasPca.Corpus.Tests;

/// <summary>The strict Ed25519 verifier (S &lt; L pre-check + BouncyCastle ValidatePublicKeyFull on A and R + BC verify) is at least
/// as strict as the TS reference (keys.ts verify: noble zip215:false + isSmallOrder + isTorsionFree on A and R). Expected values are
/// the reference's: every ed-weak-* conformance vector was generated by TS and is refused there; each is checked here at the
/// raw-signature level (pk, share_message, sig), below the signer-set checks that might otherwise refuse it first.</summary>
public class Ed25519StrictnessTests
{
    static string Dir()
    {
        var d = AppContext.BaseDirectory;
        for (int i = 0; i < 12 && d != null; i++, d = Path.GetDirectoryName(d))
        {
            var c = Path.Combine(d, "packages", "pca", "conformance");
            if (File.Exists(Path.Combine(c, "vectors.json"))) return c;
        }
        throw new InvalidOperationException("conformance dir not found");
    }

    static List<D> Shares() => ((List<object?>)((D)((D)Pca.ParseJson(File.ReadAllText(Path.Combine(Dir(), "vectors.json")))!)["primitives"]!)["threshold_share"]!)
        .Cast<D>().ToList();

    static (byte[] Pk, byte[] Msg, byte[] Sig) Raw(D v)
    {
        var share = (D)v["share"]!;
        return (Pca.B64uDecode(share["publicKey"], 32)!, Pca.B64uDecode(v["share_message"])!, Pca.B64uDecode(share["sig"], 64)!);
    }

    [Fact]
    public void EveryWeakVectorIsRefusedAtTheSignatureLevel()
    {
        var weak = Shares().Where(v => v.GetValueOrDefault("name") is string n && n.StartsWith("ed-weak-", StringComparison.Ordinal)).ToList();
        // small-order A (8 + 4 non-canonical), small-order R (8 + 6 non-canonical), mixed-order A (4), mixed-order R (4), S + L
        Assert.True(weak.Count >= 30, $"only {weak.Count} ed-weak vectors");
        foreach (var v in weak)
        {
            Assert.Equal(false, v["valid"]);
            var (pk, msg, sig) = Raw(v);
            Assert.False(Pca.VerifyEd25519Strict(pk, msg, sig), (string)v["name"]!);
        }
        foreach (var n in new[] { "small-order-A", "small-order-R", "mixed-order-A", "mixed-order-R", "noncanonical-S-plus-L" })
            Assert.Contains(weak, v => ((string)v["name"]!).Contains(n, StringComparison.Ordinal));
    }

    [Fact]
    public void WeakKeysAndRsAreNotPrimeOrderPoints()
    {
        foreach (var v in Shares().Where(v => v.GetValueOrDefault("name") is string n && n.StartsWith("ed-weak-", StringComparison.Ordinal)))
        {
            var name = (string)v["name"]!;
            var (pk, _, sig) = Raw(v);
            if (name.Contains("-A-", StringComparison.Ordinal)) Assert.False(Pca.IsPrimeOrderPoint(pk), name);
            if (name.Contains("-R-", StringComparison.Ordinal)) Assert.False(Pca.IsPrimeOrderPoint(sig[..32]), name);
            if (name.StartsWith("ed-weak-small-order-R-", StringComparison.Ordinal) || name.StartsWith("ed-weak-mixed-order-R-", StringComparison.Ordinal))
                Assert.True(Pca.IsPrimeOrderPoint(pk), name + " (honest key)");
        }
    }

    [Fact]
    public void AWrongLengthKeyOrSignatureIsRefusedNeverThrows()
    {
        var sk = new Ed25519PrivateKeyParameters(Enumerable.Range(1, 32).Select(i => (byte)i).ToArray(), 0);
        var m = "len"u8.ToArray();
        var sg = new Ed25519Signer(); sg.Init(true, sk); sg.BlockUpdate(m, 0, m.Length);
        var good = sg.GenerateSignature();
        var pub = sk.GeneratePublicKey().GetEncoded();
        Assert.True(Pca.VerifyEd25519Strict(pub, m, good));
        // a right-length key with a short signature (below 32 bytes the S half does not exist) is a refusal, not an exception
        foreach (var n in new[] { 0, 1, 10, 31, 32, 63, 65 })
            Assert.False(Pca.VerifyEd25519Strict(pub, m, good.Take(Math.Min(n, 64)).Concat(new byte[Math.Max(0, n - 64)]).ToArray()), $"signature of {n} bytes");
        // a wrong-length key with a good signature
        foreach (var n in new[] { 0, 31, 33 })
            Assert.False(Pca.VerifyEd25519Strict(pub.Take(Math.Min(n, 32)).Concat(new byte[Math.Max(0, n - 32)]).ToArray(), m, good), $"key of {n} bytes");
    }

    [Fact]
    public void HonestVectorsAndFreshSignaturesVerify()
    {
        var ok = Shares().Where(v => v.GetValueOrDefault("name") is string n && n.StartsWith("agent-bound-t", StringComparison.Ordinal)).ToList();
        Assert.NotEmpty(ok);
        foreach (var v in ok) { var (pk, msg, sig) = Raw(v); Assert.True(Pca.VerifyEd25519Strict(pk, msg, sig), (string)v["name"]!); }

        var sk = new Ed25519PrivateKeyParameters(Enumerable.Range(1, 32).Select(i => (byte)i).ToArray(), 0);
        var m = "strict"u8.ToArray();
        var s = new Ed25519Signer(); s.Init(true, sk); s.BlockUpdate(m, 0, m.Length);
        var good = s.GenerateSignature();
        var pub = sk.GeneratePublicKey().GetEncoded();
        Assert.True(Pca.VerifyEd25519Strict(pub, m, good));
        // S + L (and S + 2^253 > L) refused, as keys.test.ts 'non-canonical S'
        var L = System.Numerics.BigInteger.Pow(2, 252) + System.Numerics.BigInteger.Parse("27742317777372353535851937790883648493");
        var S = new System.Numerics.BigInteger(good.AsSpan(32), isUnsigned: true);
        foreach (var s2 in new[] { S + L, L, S + System.Numerics.BigInteger.Pow(2, 253) })
        {
            var bad = (byte[])good.Clone();
            var enc = s2.ToByteArray(isUnsigned: true); Array.Clear(bad, 32, 32); Array.Copy(enc, 0, bad, 32, Math.Min(32, enc.Length));
            Assert.False(Pca.VerifyEd25519Strict(pub, m, bad));
        }
        // identity key with (R = identity, S = 0): plain RFC 8032 accepts; strict refuses (keys.test.ts)
        var id = new byte[32]; id[0] = 1;
        var forged = new byte[64]; forged[0] = 1;
        Assert.False(Pca.VerifyEd25519Strict(id, m, forged));
    }
}
